window.AUTH=window.AUTH||{};window.AUTH["22-976"]={"d":"22-976","id":"2023/22-976","n":"Garland v. Cargill","briefs":[{"k":"petitioner","label":"Brief of petitioners Merrick B. Garland, et al.","date":"2023-12-18","url":"https://www.supremecourt.gov/DocketPDF/22/22-976/293668/20231218165513713_22-976tsUnitedStates.pdf","side":"pet","n":38},{"k":"respondent","label":"Brief of respondent Michael Cargill","date":"2024-01-22","url":"https://www.supremecourt.gov/DocketPDF/22/22-976/298344/20240122163801884_Respondent%20Brief%20on%20the%20Merits.pdf","side":"res","n":42},{"k":"reply","label":"Reply of petitioners Merrick B. Garland, et al.","date":"2024-02-16","url":"https://www.supremecourt.gov/DocketPDF/22/22-976/300779/20240216121411253_22-976rbUnitedStates.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/602us1r36_k537.pdf","tr":true,"items":[{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"op":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"0":"38, 39, 42, 45","1":"17, 46, 48, 49","2":"18"}},{"t":"case","label":"Akins v. United States","cite":"312 Fed. Appx. 197","y":2009,"url":"https://www.courtlistener.com/c/Fed.%20Appx./312/197/","op":2,"ar":5,"sum":"Upholding classifcation of Akins Accelerator, a spring-operated bump stock.","sumSrc":"opinion","by":{"0":"8, 27, 43","1":"6"}},{"t":"case","label":"American Broadcasting Cos. v. Aereo, Inc.","cite":"573 U.S. 431","y":2014,"id":"2013/13-461","sc":1,"sum":"The Court held that Aereo, Inc. violated federal copyright law by allowing users to stream content produced by major cable companies without a cable subscription.","sumSrc":"Oyez","by":{"0":"38-41","1":"46","2":"17"}},{"t":"case","label":"Bank Markazi v. Peterson","cite":"578 U.S. 212","y":2016,"id":"2015/14-770","sc":1,"op":1,"sum":"The Court decided that a statute effectively directing a particular result in a single pending case does not violate the separation of powers.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"County of Maui v. Hawaii Wildlife Fund","cite":"140 S. Ct. 1462","y":2020,"id":"2019/18-260","sc":1,"sum":"The Court held the Clean Water Act requires a permit when pollutants originate from a point source but are conveyed to navigable waters by a nonpoint source, such as groundwater, if the conveyance is the \"functional equivalent\" of a direct discharge.","sumSrc":"Oyez","by":{"0":"38, 40, 42","1":"46"}},{"t":"case","label":"(III) Cases—Continued: FCC v. Fox Television Stations, Inc.","cite":"556 U.S. 502","y":2009,"id":"2008/07-582","sc":1,"sum":"The Court held that the FCC's imposition of liability on Fox Television Stations for fleeting expletives was not \"arbitrary and capricious\" under the Administrative Procedure Act, even though the FCC previously accepted similar expletives.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Gun Owners of America, Inc. v. Garland","cite":"19 F.4th 890","y":2021,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/19/890/","op":1,"by":{"0":"36","1":"4"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"McDonald v. City of Chicago","cite":"561 U.S. 742","y":2010,"id":"2009/08-1521","sc":1,"op":1,"ar":1,"sum":"The Court held that the Fourteenth Amendment makes the Second Amendment's right to bear arms for the purpose of self-defense applicable in the states.","sumSrc":"Oyez","by":{"0":"20","2":"4"}},{"t":"case","label":"National Ass’n for Gun Rights v. Garland","cite":"2023 WL 6613080","y":2023,"court":"N.D. Tex. Oct. 7","by":{"0":"28"}},{"t":"case","label":"New England Power Generators Ass’n v. FERC","cite":"879 F.3d 1192","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/879/1192/","by":{"0":"44"}},{"t":"case","label":"Norwegian Nitrogen Products Co. v. United States","cite":"288 U.S. 294","y":1933,"id":"scdb/1932-150","sc":1,"sum":"The Tariff Act of 1922 empowers the President to change rates of duty in order to equalize differences in costs of production in this country and abroad, but provides--§ 315 (c)-that before he acts there shall have been an investigation of such differences by the Tariff Commission, in the making of which the Commission shall give reasonable public notice of its hearings, and shall give \"reasonable opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"sum":"The Court determined that a conspiracy to commit extortion can involve the purported victims of the extortion as members of the conspiracy.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Springfield Armory, Inc. v. City of Columbus","cite":"29 F.3d 250","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/29/250/","by":{"0":"2"}},{"t":"case","label":"Staples v. United States","cite":"511 U.S. 600","y":1994,"id":"1993/92-1441","sc":1,"op":1,"ar":2,"sum":"To obtain a § 5861(d) conviction, the Government should have been required to prove beyond a reasonable doubt that Staples knew that his rifle had the characteristics that brought it within the statutory definition of a machinegun.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 14, 21, 25, 32, 33, 36","1":"2","2":"5, 13"}},{"t":"case","label":"United States v. Bishop","cite":"926 F.3d 621","y":2019,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/926/621/","by":{"0":"21"}},{"t":"case","label":"United States v. Camp","cite":"343 F.3d 743","y":2003,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/343/743/","op":2,"ar":9,"sum":"Upholding classifcation of fshing reel attached to a rife trigger that, upon activation, repeatedly operated the curved lever of the rife.","sumSrc":"opinion","by":{"0":"18, 22, 29","1":"47","2":"9"}},{"t":"case","label":"United States v. Carter","cite":"465 F.3d 658","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/658/","by":{"0":"22"}},{"t":"case","label":"United States v. Evans","cite":"978 F.2d 1112","y":1992,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/978/1112/","by":{"0":"18"}},{"t":"case","label":"United States v. Fleischli","cite":"305 F.3d 643","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/305/643/","by":{"0":"18, 22"}},{"t":"case","label":"United States v. Harris","cite":"959 F.2d 246","y":1992,"url":"https://www.courtlistener.com/c/F.2d/959/246/","by":{"0":"21"}},{"t":"case","label":"United States v. Jokel","cite":"969 F.2d 132","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/969/132/","by":{"0":"18, 22"}},{"t":"case","label":"United States v. O’Brien","cite":"560 U.S. 218","y":2010,"id":"2009/08-1569","sc":1,"sum":"The Court held that the fact that a firearm was a machine gun is an element to be proved to the jury beyond a reasonable doubt, not a sentencing factor to be proved to the judge at sentencing.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"United States v. Olofson","cite":"563 F.3d 652","y":2009,"url":"https://www.courtlistener.com/c/F.3d/563/652/","by":{"0":"18, 21"}},{"t":"case","label":"United States v. Rare Breed Triggers, LLC","cite":"2023 WL 5689770","y":2023,"court":"E.D.N.Y. Sept. 5","by":{"0":"28","2":"11"}},{"t":"case","label":"United States v. Smith","cite":"700 F.2d 627","y":1983,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/700/627/","by":{"0":"21"}},{"t":"case","label":"United States v. Vázquez-Martínez","cite":"812 F.3d 18","y":2016,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/812/18/","by":{"0":"21"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"45"}},{"t":"law","label":"and regulation: Firearms Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/449","by":{"0":"3"}},{"t":"law","label":"Pub. L. No. 90-618","url":"https://www.govinfo.gov/link/statute/82/1213","by":{"0":"3"}},{"t":"usc","label":"18 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/18/921","subs":["(a)(24)","(a)(29)"],"stext":{"head":"§921. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"person\" and the term \"whoever\" include any individual, corporation, company, association, firm, partnership, society, or joint stock company."],[0,"(2) The term \"interstate or foreign commerce\" includes commerce between any place in a State and any place outside of that State, or within any possession of the United States (not including the Canal Zone) or the District of Columbia, but such term does not include commerce between places within the same State but through any place outside of that State. The term \"State\" includes the District of Columbia, the Commonwealth of Puerto Rico, and the possessions of the United States (not including the Canal Zone)."],[0,"(3) The term \"firearm\" means (A) any weapon (including a starter gun) which will or is designed to or may readily be converted to expel a projectile by the action of an explosive; (B) the frame or receiver of any such weapon; (C) any firearm muffler or firearm silencer; or (D) any destructive device. Such term does not include an antique firearm."],[0,"(4) The term \"destructive device\" means—"],[1,"(A) any explosive, incendiary, or poison gas—"],[2,"(i) bomb,"],[2,"(ii) grenade,"],[2,"(iii) rocket having a propellant charge of more than four ounces,"],[2,"(iv) missile having an explosive or incendiary charge of more than one-quarter ounce,"],[2,"(v) mine, or"],[2,"(vi) device similar to any of the devices described in the preceding clauses;"],[1,"(B) any type of weapon (other than a shotgun or a shotgun shell which the Attorney General finds is generally recognized as particularly suitable for sporting purposes) by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, and which has any barrel with a bore of more than one-half inch in diameter; and"],[1,"(C) any combination of parts either designed or intended for use in converting any device into any destructive device described in subparagraph (A) or (B) and from which a destructive device may be readily assembled."],[0,"The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10; or any other device which the Attorney General finds is not likely to be used as a weapon, is an antique, or is a rifle which the owner intends to use solely for sporting, recreational or cultural purposes."],[0,"(5) The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire through a smooth bore either a number of ball shot or a single projectile for each single pull of the trigger."],[0,"(6) The term \"short-barreled shotgun\" means a shotgun having one or more barrels less than eighteen inches in length and any weapon made from a shotgun (whether by alteration, modification or otherwise) if such a weapon as modified has an overall length of less than twenty-six inches."],[0,"(7) The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of an explosive to fire only a single projectile through a rifled bore for each single pull of the trigger."],[0,"(8) The term \"short-barreled rifle\" means a rifle having one or more barrels less than sixteen inches in length and any weapon made from a rifle (whether by alteration, modification, or otherwise) if such weapon, as modified, has an overall length of less than twenty-six inches."],[0,"(9) The term \"importer\" means any person engaged in the business of importing or bringing firearms or ammunition into the United States for purposes of sale or distribution; and the term \"licensed importer\" means any such person licensed under the provisions of this chapter."],[0,"(10) The term \"manufacturer\" means any person engaged in the business of manufacturing firearms or ammunition for purposes of sale or distribution; and the term \"licensed manufacturer\" means any such person licensed under the provisions of this chapter."],[0,"(11) The term \"dealer\" means (A) any person engaged in the business of selling firearms at wholesale or retail, (B) any person engaged in the business of repairing firearms or of making or fitting special barrels, stocks, or trigger mechanisms to firearms, or (C) any person who is a pawnbroker. The term \"licensed dealer\" means any dealer who is licensed under the provisions of this chapter."],[0,"(12) The term \"pawnbroker\" means any person whose business or occupation includes the taking or receiving, by way of pledge or pawn, of any firearm as security for the payment or repayment of money."],[0,"(13) The term \"collector\" means any person who acquires, holds, or disposes of firearms as curios or relics, as the Attorney General shall by regulation define, and the term \"licensed collector\" means any such person licensed under the provisions of this chapter."],[0,"(14) The term \"indictment\" includes an indictment or information in any court under which a crime punishable by imprisonment for a term exceeding one year may be prosecuted."],[0,"(15) The term \"fugitive from justice\" means any person who has fled from any State to avoid prosecution for a crime or to avoid giving testimony in any criminal proceeding."],[0,"(16) The term \"antique firearm\" means—"],[1,"(A) any firearm (including any firearm with a matchlock, flintlock, percussion cap, or similar type of ignition system) manufactured in or before 1898; or"],[1,"(B) any replica of any firearm described in subparagraph (A) if such replica—"],[2,"(i) is not designed or redesigned for using rimfire or conventional centerfire fixed ammunition, or"],[2,"(ii) uses rimfire or conventional centerfire fixed ammunition which is no longer manufactured in the United States and which is not readily available in the ordinary channels of commercial trade; or"],[1,"(C) any muzzle loading rifle, muzzle loading shotgun, or muzzle loading pistol, which is designed to use black powder, or a black powder substitute, and which cannot use fixed ammunition. For purposes of this subparagraph, the term \"antique firearm\" shall not include any weapon which incorporates a firearm frame or receiver, any firearm which is converted into a muzzle loading weapon, or any muzzle loading weapon which can be readily converted to fire fixed ammunition by replacing the barrel, bolt, breechblock, or any combination thereof."],[0,"(17)(A) The term \"ammunition\" means ammunition or cartridge cases, primers, bullets, or propellent powder designed for use in any firearm."],[0,"(B) The term \"armor piercing ammunition\" means—"],[1,"(i) a projectile or projectile core which may be used in a handgun and which is constructed entirely (excluding the presence of traces of other substances) from one or a combination of tungsten alloys, steel, iron, brass, bronze, beryllium copper, or depleted uranium; or"],[1,"(ii) a full jacketed projectile larger than .22 caliber designed and intended for use in a handgun and whose jacket has a weight of more than 25 percent of the total weight of the projectile."],[0,"(C) The term \"armor piercing ammunition\" does not include shotgun shot required by Federal or State environmental or game regulations for hunting purposes, a frangible projectile designed for target shooting, a projectile which the Attorney General finds is primarily intended to be used for sporting purposes, or any other projectile or projectile core which the Attorney General finds is intended to be used for industrial purposes, including a charge used in an oil and gas well perforating device."],[0,"(18) The term \"Attorney General\" means the Attorney General of the United States 1"],[0,"(19) The term \"published ordinance\" means a published law of any political subdivision of a State which the Attorney General determines to be relevant to the enforcement of this chapter and which is contained on a list compiled by the Attorney General, which list shall be published in the Federal Register, revised annually, and furnished to each licensee under this chapter."],[0,"(20) The term \"crime punishable by imprisonment for a term exceeding one year\" does not include—"],[1,"(A) any Federal or State offenses pertaining to antitrust violations, unfair trade practices, restraints of trade, or other similar offenses relating to the regulation of business practices, or"],[1,"(B) any State offense classified by the laws of the State as a misdemeanor and punishable by a term of imprisonment of two years or less."],[0,"What constitutes a conviction of such a crime shall be determined in accordance with the law of the jurisdiction in which the proceedings were held. Any conviction which has been expunged, or set aside or for which a person has been pardoned or has had civil rights restored shall not be considered a conviction for purposes of this chapter, unless such pardon, expungement, or restoration of civil rights expressly provides that the person may not ship, transport, possess, or receive firearms."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/921?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§921. Definitions","tname":"Crimes and Criminal Procedure","by":{"0":"38","1":"3"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(o)(1)","(o)(2)(B)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"38, 38","1":"2, 2","2":"16"}},{"t":"usc","label":"26 U.S.C. § 5845","url":"https://www.law.cornell.edu/uscode/text/26/5845","subs":["(b)","(e)"],"stext":{"head":"§5845. Definitions","paras":[[0,"For the purpose of this chapter—"],[0,"(a) Firearm"],[0,"The term \"firearm\" means (1) a shotgun having a barrel or barrels of less than 18 inches in length; (2) a weapon made from a shotgun if such weapon as modified has an overall length of less than 26 inches or a barrel or barrels of less than 18 inches in length; (3) a rifle having a barrel or barrels of less than 16 inches in length; (4) a weapon made from a rifle if such weapon as modified has an overall length of less than 26 inches or a barrel or barrels of less than 16 inches in length; (5) any other weapon, as defined in subsection (e); (6) a machinegun; (7) any silencer (as defined in section 921 of title 18, United States Code); and (8) a destructive device. The term \"firearm\" shall not include an antique firearm or any device (other than a machinegun or destructive device) which, although designed as a weapon, the Secretary finds by reason of the date of its manufacture, value, design, and other characteristics is primarily a collector's item and is not likely to be used as a weapon."],[0,"(b) Machinegun"],[0,"The term \"machinegun\" means any weapon which shoots, is designed to shoot, or can be readily restored to shoot, automatically more than one shot, without manual reloading, by a single function of the trigger. The term shall also include the frame or receiver of any such weapon, any part designed and intended solely and exclusively, or combination of parts designed and intended, for use in converting a weapon into a machinegun, and any combination of parts from which a machinegun can be assembled if such parts are in the possession or under the control of a person."],[0,"(c) Rifle"],[0,"The term \"rifle\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of the explosive in a fixed cartridge to fire only a single projectile through a rifled bore for each single pull of the trigger, and shall include any such weapon which may be readily restored to fire a fixed cartridge."],[0,"(d) Shotgun"],[0,"The term \"shotgun\" means a weapon designed or redesigned, made or remade, and intended to be fired from the shoulder and designed or redesigned and made or remade to use the energy of the explosive in a fixed shotgun shell to fire through a smooth bore either a number of projectiles (ball shot) or a single projectile for each pull of the trigger, and shall include any such weapon which may be readily restored to fire a fixed shotgun shell."],[0,"(e) Any other weapon"],[0,"The term \"any other weapon\" means any weapon or device capable of being concealed on the person from which a shot can be discharged through the energy of an explosive, a pistol or revolver having a barrel with a smooth bore designed or redesigned to fire a fixed shotgun shell, weapons with combination shotgun and rifle barrels 12 inches or more, less than 18 inches in length, from which only a single discharge can be made from either barrel without manual reloading, and shall include any such weapon which may be readily restored to fire. Such term shall not include a pistol or a revolver having a rifled bore, or rifled bores, or weapons designed, made, or intended to be fired from the shoulder and not capable of firing fixed ammunition."],[0,"(f) Destructive device"],[0,"The term \"destructive device\" means (1) any explosive, incendiary, or poison gas (A) bomb, (B) grenade, (C) rocket having a propellent charge of more than four ounces, (D) missile having an explosive or incendiary charge of more than one-quarter ounce, (E) mine, or (F) similar device; (2) any type of weapon by whatever name known which will, or which may be readily converted to, expel a projectile by the action of an explosive or other propellant, the barrel or barrels of which have a bore of more than one-half inch in diameter, except a shotgun or shotgun shell which the Secretary finds is generally recognized as particularly suitable for sporting purposes; and (3) any combination of parts either designed or intended for use in converting any device into a destructive device as defined in subparagraphs (1) and (2) and from which a destructive device may be readily assembled. The term \"destructive device\" shall not include any device which is neither designed nor redesigned for use as a weapon; any device, although originally designed for use as a weapon, which is redesigned for use as a signaling, pyrotechnic, line throwing, safety, or similar device; surplus ordnance sold, loaned, or given by the Secretary of the Army pursuant to the provisions of section 7684(2), 7685, or 7686 of title 10, United States Code; or any other device which the Secretary finds is not likely to be used as a weapon, or is an antique or is a rifle which the owner intends to use solely for sporting purposes."],[0,"(g) Antique firearm"],[0,"The term \"antique firearm\" means any firearm not designed or redesigned for using rim fire or conventional center fire ignition with fixed ammunition and manufactured in or before 1898 (including any matchlock, flintlock, percussion cap, or similar type of ignition system or replica thereof, whether actually manufactured before or after the year 1898) and also any firearm using fixed ammunition manufactured in or before 1898, for which ammunition is no longer manufactured in the United States and is not readily available in the ordinary channels of commercial trade."],[0,"(h) Unserviceable firearm"],[0,"The term \"unserviceable firearm\" means a firearm which is incapable of discharging a shot by means of an explosive and incapable of being readily restored to a firing condition."],[0,"(i) Make"],[0,"The term \"make\", and the various derivatives of such word, shall include manufacturing (other than by one qualified to engage in such business under this chapter), putting together, altering, any combination of these, or otherwise producing a firearm."],[0,"(j) Transfer"],[0,"The term \"transfer\" and the various derivatives of such word, shall include selling, assigning, pledging, leasing, loaning, giving away, or otherwise disposing of."],[0,"(k) Dealer"],[0,"The term \"dealer\" means any person, not a manufacturer or importer, engaged in the business of selling, renting, leasing, or loaning firearms and shall include pawnbrokers who accept firearms as collateral for loans."],[0,"(l) Importer"],[0,"The term \"importer\" means any person who is engaged in the business of importing or bringing firearms into the United States."],[0,"(m) Manufacturer"],[0,"The term \"manufacturer\" means any person who is engaged in the business of manufacturing firearms."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/5845?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§5845. Definitions","tname":"Internal Revenue Code","by":{"0":"38, 38","1":"i, 2, 3, 9, 10, 13, 16, 17, 23, 24, 25, 26, 28, 34, 35, 38, 39, 43, 44, 45, 46, 47, 48, 49, 50","2":"2, 3, 6, 7, 9, 13, 15"}},{"t":"reg","label":"27 C.F.R. § 479.11","url":"https://www.ecfr.gov/current/title-27/section-479.11","by":{"0":"20","1":"10","2":"16"}},{"t":"reg","label":"82 Fed. Reg. 60,929","url":"https://www.govinfo.gov/link/fr/82/60929","by":{"0":"9","1":"9"}},{"t":"reg","label":"83 Fed. Reg. 66,514","url":"https://www.govinfo.gov/link/fr/83/66514","by":{"0":"5-11, 22, 23, 27, 28, 31, 32, 36-38, 41, 43","1":"1, 4, 5, 6, 7, 8, 10, 11, 31","2":"3, 19, 20"}},{"t":"case","label":"Board of Governors v. Dimension Financial Corp.","cite":"474 U.S. 361","y":1986,"id":"1985/84-1274","sc":1,"sum":"The Board did not act within its statutory authority in defining \"banks\" as it did.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"Bostock v. Clayton County","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"sum":"The Court held that Title VII of the Civil Rights Act of 1964, which prohibits against employment discrimination “because of . . . sex” encompasses discrimination based on an individual’s sexual orientation.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Bouie v. City of Columbia","cite":"378 U.S. 347","y":1964,"id":"1963/10","sc":1,"sum":"The State Supreme Court, in giving retroactive application to its new construction of the statute, has deprived petitioners of their right to fair warning of a criminal prohibition, and thus has violated the Due Process Clause of the Fourteenth Amendment. Pp. 348-363. 239 S. C. 570, 124 S. E. 2d 332, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Chevron U.S.A., Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"11, 17","2":"20"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"1":"35, 47","2":"19, 20"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Fla. Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Epic Systems Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"23–24"}},{"t":"case","label":"Graham County Soil and Water Conservation Dist. v. U.S. ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Griffin v. HM Fla.-ORL, LLC","cite":"144 S. Ct. 1","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./144/1/","sc":1,"by":{"1":"50"}},{"t":"case","label":"Guedes v. Bureau of Alcohol, Tobacco. Firearms, and Explosives","cite":"920 F.3d 1","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/920/1/","op":2,"ar":1,"by":{"1":"42"}},{"t":"case","label":"Henry Schein, Inc. v. Archer & White Sales, Inc.","cite":"139 S. Ct. 524","y":2019,"id":"2018/17-1272","sc":1,"sum":"The “wholly groundless” exception to the general rule that courts must enforce contracts that delegate threshold arbitrability questions to an arbitrator, not a court, is inconsistent with the Federal Arbitration Act and this Court’s precedent.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"582 U.S. 79","y":2017,"id":"2016/16-349","sc":1,"op":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Lamie v. U.S. Trustee","cite":"540 U.S. 526","y":2004,"id":"2003/02-693","sc":1,"sum":"According to Justice Anthony Kennedy's opinion for the Court: \"The statute is awkward, and even ungrammatical; but that does not make it ambiguous on the point at issue.\" The Court ruled that though the Act's deletion of the words \"or to the debtor's attorney\" from the Bankruptcy Code had rendered a sentence grammatically incorrect, the Act should still be interpreted according to the plain meaning of its text, however awkward.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Lewis v. Chicago","cite":"560 U.S. 205","y":2010,"id":"2009/08-974","sc":1,"sum":"The Court held that an employee may file a Title VII disparate impact claim within 300 days after their employer executes the allegedly unlawful practice.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Magwood v. Patterson","cite":"561 U.S. 320","y":2010,"id":"2009/09-158","sc":1,"sum":"The Court held that, when a habeas corpus application alleges new judgment for the first time, it is not \"second or successive\" under the Antiterrorism and Effective Death Penalty Act and is therefore constitutional.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"MCI Telecommunications Corp. v. AT&T Co.","cite":"512 U.S. 218","y":1994,"id":"1993/93-356","sc":1,"sum":"The Commission's permissive detariffing policy is not a valid exercise of its §203(b)(2) authority to \"modify any requirement.\" Because virtually every dictionary in use now and at the time the statute was enacted defines \"to modify\" as meaning to change moderately or in minor fashion, the word \"modify\" must be seen to have a connotation of increment or limitation. That § 203(b)(2) does not contemplate basic or …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Norfolk S. Ry. Co. v. Sorrell","cite":"549 U.S. 158","y":2007,"id":"2006/05-746","sc":1,"sum":"The Court ruled unanimously that the causation standard for employee negligence is the same as the standard for railroad negligence.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Seila Law LLC v. Consumer Financial Protection Bureau","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"United States v. Alkazahg","cite":"81 M.J. 764","y":2021,"court":"N-M. Ct. Crim. App.","url":"https://www.courtlistener.com/c/M.J./81/764/","sum":"Holding that the “structure and text” of 26 U.S.C. § 5845(b) “will not allow” a court “to judicially transform the phrase ‘by a single function of the trigger’ into ‘by a single pull of the trigger.’ ”.","sumSrc":"brief:1","by":{"1":"25"}},{"t":"case","label":"United States v. Apel","cite":"571 U.S. 359","y":2014,"id":"2013/12-1038","sc":1,"sum":"The Court ruled that a federal statute can be enforced on a portion of military land that is subject to a public roadway easement.","sumSrc":"Oyez","by":{"1":"17, 48"}},{"t":"case","label":"Whole Woman’s Health v. Jackson","cite":"141 S. Ct. 2494","y":2021,"id":"2021/21-463","sc":1,"sum":"A pre-enforcement challenge under the Federal Constitution to Texas Senate Bill 8—the Texas Heartbeat Act—may proceed past the motion to dismiss stage against certain of the named defendants but not others; the order of the District Court is affirmed in part and reversed in part, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"50–51"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)","(2)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"1":"12, 17, 50, 12, 50","2":"20"}},{"t":"reg","label":"16 C.F.R. § 401.1","url":"https://www.ecfr.gov/current/title-16/section-401.1","subs":["(b)"],"by":{"1":"44","2":"16"}},{"t":"reg","label":"16 C.F.R. § 401.2","url":"https://www.ecfr.gov/current/title-16/section-401.2","by":{"1":"44"}},{"t":"reg","label":"27 C.F.R. § 447.11","url":"https://www.ecfr.gov/current/title-27/section-447.11","by":{"1":"10"}},{"t":"reg","label":"27 C.F.R. § 478.11","url":"https://www.ecfr.gov/current/title-27/section-478.11","by":{"1":"10"}},{"t":"reg","label":"ATF, Bump-Stock-Type Devices, 83 Fed. Reg. 13,442","url":"https://www.govinfo.gov/link/fr/83/13442","by":{"1":"9"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"HollyFrontier Cheyenne Refining, LLC v. Renewable Fuels Ass’n","cite":"141 S. Ct. 2172","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"20"}},{"t":"case","label":"NYSRPA v. Bruen","cite":"597 U.S. 1","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/1/","sc":1,"by":{"2":"19, 20"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Northwest Airlines, Inc. v. County of Kent","cite":"510 U.S. 355","y":1994,"id":"1993/92-97","sc":1,"sum":"Respondents, the owner and operators of Michigan's Kent County International Airport (collectively, the Airport), collect rent and fees from three groups of Airport users: commercial airlines, including petitioners (Airlines); general aviation; and concessionaires such as car rental agencies and gift shops. The Airport allocates its air-operations costs---e. g., maintaining runways-to the Airlines and general …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"(I) Cases—Continued: United States v. Pennsylvania Indus. Chem. Corp.","cite":"411 U.S. 655","y":1973,"id":"1972/72-624","sc":1,"sum":"After the District Court refused respondent's offers of proof of reliance on Army Corps of Engineers regulations limiting violations to those impeding navigation, respondent was convicted of violating § 13 of the Rivers and Harbors Act of 1899 by discharging industrial pollutants into a navigable river. The Court of Appeals reversed on the ground that § 13 did not apply absent formalized permit procedures or, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"21"}},{"t":"case","label":"Whitfield v. United States","cite":"574 U.S. 265","y":2015,"id":"2014/13-9026","sc":1,"sum":"The Court held that forced accompaniment during the commission of a crime occurs when a person requires another to “go with” him, even when that movement occurs over a short distance.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"const","label":"Amendment II","clauses":[["second-amendment","Second Amendment"]],"text":"A well regulated Militia, being necessary to the security of a free State, the right of the people to keep and bear Arms, shall not be infringed.","by":{"2":"19, 20"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"18"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"2":"20"}}]};